import { Amplify } from 'aws-amplify'
import { cognitoUserPoolsTokenProvider } from 'aws-amplify/auth/cognito'
import { defaultStorage } from 'aws-amplify/utils'
import { createRoot } from 'react-dom/client'
import './index.css'
import App from './App'
// Loaded after every other stylesheet so its width queries win: the responsive layer for tablets and phones.
import './features/tms/responsive.css'
import { registerDriverServiceWorker } from './lib/swUpdate'
import { reloadForStaleChunk } from './lib/staleChunk'

// amplify_outputs.json is generated by Amplify during the build pipeline.
// The placeholder file in the repo is replaced with real values on every deploy.
// For local dev, run: npx ampx sandbox
import outputs from '../amplify_outputs.json'
Amplify.configure(outputs as Parameters<typeof Amplify.configure>[0])

// Persist the auth session in localStorage (NOT sessionStorage) so users stay logged
// in across browser restarts/tab closes on mobile and desktop — until they explicitly
// log out. The session lasts as long as the Cognito refresh token (60 days; set on the
// user-pool client in amplify/backend.ts), refreshing the short-lived tokens silently.
cognitoUserPoolsTokenProvider.setKeyValueStorage(defaultStorage)

// A tab opened before a deploy asks for page chunks that no longer exist: reload once to pick up the new build.
window.addEventListener('vite:preloadError', (event) => {
  if (reloadForStaleChunk()) event.preventDefault()
})

createRoot(document.getElementById('root')!).render(
  <App />
)

// The driver PWA keeps itself current — see src/lib/swUpdate.ts. No-op on staff routes.
registerDriverServiceWorker()
